CREATE OR REPLACE PROCEDURE sp(
    arg1 NUMBER,
    arg2 VARCHAR2,
    arg3 VARCHAR2,
    arg4 VARCHAR2
)
AS
BEGIN
    -- 1. Pre-deletion pass over operators older than arg1
    UPDATE driver d
       SET d."Name" = arg2
     WHERE d."Age" > arg1;

    FOR rec IN (
        SELECT b."School_ID", b."Driver_ID"
          FROM school_bus b
          JOIN driver d ON d."Driver_ID" = b."Driver_ID"
         WHERE d."Age" > arg1
    ) LOOP
        UPDATE school_bus b
           SET b."Years_Working" = NVL(b."Years_Working", 0) + 1
         WHERE b."School_ID" = rec."School_ID";

        IF arg3 IS NOT NULL THEN
            FOR drec IN (
                SELECT "Party" FROM driver
                 WHERE "Driver_ID" = rec."Driver_ID"
            ) LOOP
                IF drec."Party" = arg3 THEN
                    UPDATE school_bus b
                       SET b."If_full_time" = 'T'
                     WHERE b."School_ID" = rec."School_ID";
                END IF;
            END LOOP;
        END IF;
    END LOOP;

    -- 2. Delete operators with null party
    DELETE FROM driver WHERE "Party" IS NULL;

    -- 3. All remaining drivers: home city = arg4
    UPDATE driver SET "Home_city" = arg4;

    -- 4. Only when arg3 is not null
    IF arg3 IS NOT NULL THEN
        UPDATE driver
           SET "Party" = arg3
         WHERE "Age" > arg1;

        UPDATE school_bus b
           SET b."If_full_time" = 'F'
         WHERE b."Driver_ID" IN (
                   SELECT d."Driver_ID" FROM driver d
                    WHERE d."Party" = arg3 AND d."Age" <= arg1
               );
    END IF;
END sp;

